import apps.achievements.models

BADGE_NAME_DIGITS = 5
PLACEHOLDER_BADGE_NAME = "0" * BADGE_NAME_DIGITS


def move_badge_uploads_to_badges(apps, schema_editor):
    """An achievement's uploaded badge becomes the badge named after the achievement, the name
    it was served under; an achievement without an upload shows the placeholder."""
    Achievement = apps.get_model("achievements", "Achievement")
    Badge = apps.get_model("achievements", "Badge")
    for achievement in Achievement.objects.exclude(badge="").exclude(badge__isnull=True):
        Badge.objects.create(pk=achievement.pk, image=achievement.badge.name)
        achievement.badge_name = f"{achievement.pk:0{BADGE_NAME_DIGITS}d}"
        achievement.save(update_fields=["badge_name"])
    # Badges were created with explicit ids; the next upload must be numbered past them.
    for statement in schema_editor.connection.ops.sequence_reset_sql(no_style(), [Badge]):
        schema_editor.execute(statement)


def move_badges_back_to_achievements(apps, schema_editor):
    Achievement = apps.get_model("achievements", "Achievement")
    Badge = apps.get_model("achievements", "Badge")
    for achievement in Achievement.objects.exclude(badge_name=PLACEHOLDER_BADGE_NAME):
        badge = Badge.objects.filter(pk=int(achievement.badge_name)).first()
        if badge is not None:
            achievement.badge = badge.image.name
            achievement.save(update_fields=["badge"])


